from fastapi import FastAPI

from app.observability import initialize_neatlogs, shutdown_neatlogs
from app.service import run_improvement_cycle


@asynccontextmanager
async def lifespan(app: FastAPI):
    initialize_neatlogs()
    try:
        yield
    finally:
        shutdown_neatlogs()


